insert into courses (id, slug, title, title_en, order_index, tags, free_tier_included, level, parent_course_id, required_tier, content, content_en) values
('b0000000-0000-0000-0000-000000000001', 'demarrer-conversation', $$Démarrer une conversation$$, $$Starting a conversation$$, 1, ARRAY['conversation', 'debuter']::text[], true, 1, null, 'free', $json${"hook":"Tu es à une soirée. Tu vois un petit groupe qui rigole près du buffet. Ton cerveau te souffle : \"Ils ont l'air occupés, n'y va pas.\" Ton corps se fige. Cette scène, presque tous les introvertis la connaissent. Ce que ton cerveau vient de te dire est scientifiquement prévisible. Une étude a montré qu'il se trompe à tous les coups.","diagnostic":{"kind":"slider","question":"À quel point te sens-tu à l'aise pour aborder une personne que tu ne connais pas ?","min":1,"max":10,"minLabel":"Terrifié","maxLabel":"Aucun souci"},"cards":[{"title":"L'écart de sympathie","advice":"La personne en face de toi a presque toujours mieux vécu l'échange que ce que tu imagines après coup.","sourceId":"a0000000-0000-0000-0000-000000000001"},{"title":"La méthode FORD","advice":"Quand tu ne sais pas quoi dire, pense Famille, Occupation, loisirs (Récréation), Rêves : les 4 sujets qui ouvrent une conversation naturellement.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Question ouverte, pas fermée","advice":"\"Qu'est-ce qui t'amène ici ce soir ?\" donne un vrai espace de réponse ; \"Tu t'amuses ?\" tue la conversation en un mot.","sourceId":"a0000000-0000-0000-0000-000000000003"},{"title":"Le commentaire de contexte","advice":"Le moyen le plus simple de démarrer : commenter ce qui vous entoure, ici et maintenant.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Pose la question, puis tais-toi vraiment","advice":"Écoute réellement la réponse, ne prépare pas déjà ta prochaine phrase.","sourceId":"a0000000-0000-0000-0000-000000000004"},{"title":"Récap","advice":"Contexte ou FORD pour ouvrir, question ouverte pour laisser de la place, écart de sympathie pour te rassurer.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"File d'attente pour un café, 10 secondes avant ton tour. Qu'est-ce que tu dirais ?","examples":["\"Ce café a l'air hyper populaire, tu viens souvent ?\" (commentaire de contexte)","\"Vous bossez dans le coin ?\" (FORD, occupation)","\"Qu'est-ce que vous recommandez ici ?\" (question ouverte)"]},"personalization":{"condition":"<=4","reorderCardIndexFirst":0}}$json$::jsonb, $json${"hook":"You're at a party. You see a small group laughing near the buffet. Your brain whispers: \"They look busy, don't bother.\" Your body freezes. Almost every introvert knows this scene. What your brain just told you is scientifically predictable. One study showed it's wrong every single time.","diagnostic":{"kind":"slider","question":"How comfortable do you feel approaching someone you don't know?","min":1,"max":10,"minLabel":"Terrified","maxLabel":"No problem at all"},"cards":[{"title":"The liking gap","advice":"The person in front of you almost always came away from the exchange feeling better about it than you imagine afterward.","sourceId":"a0000000-0000-0000-0000-000000000001"},{"title":"The FORD method","advice":"When you don't know what to say, think Family, Occupation, Recreation, Dreams: the 4 topics that open a conversation naturally.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Open question, not closed","advice":"\"What brings you here tonight?\" gives real room to answer; \"Having fun?\" kills the conversation in one word.","sourceId":"a0000000-0000-0000-0000-000000000003"},{"title":"The context comment","advice":"The simplest way to start: comment on what's around you, here and now.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Ask, then actually stay quiet","advice":"Really listen to the answer, don't already be preparing your next line.","sourceId":"a0000000-0000-0000-0000-000000000004"},{"title":"Recap","advice":"Context or FORD to open, an open question to leave room, the liking gap to reassure yourself.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Coffee line, 10 seconds before your turn. What would you say?","examples":["\"This coffee shop looks really popular, do you come here often?\" (context comment)","\"Do you work around here?\" (FORD, occupation)","\"What do you recommend here?\" (open question)"]},"personalization":{"condition":"<=4","reorderCardIndexFirst":0}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000002', 'gerer-silence-genant', $$Gérer un silence gênant$$, $$Handling an awkward silence$$, 2, ARRAY['conversation']::text[], false, 1, null, 'premium', $json${"hook":"Tu es en tête-à-tête, la conversation ralentit, puis s'arrête. Trois secondes passent. Ton cœur s'accélère, tu cherches désespérément une phrase, n'importe laquelle. Ce malaise a une explication précise : des chercheurs ont mesuré, au dixième de seconde près, à quel moment un silence commence à faire mal, et pourquoi.","diagnostic":{"kind":"slider","question":"À quel point un silence de quelques secondes dans une conversation te met-il mal à l'aise ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Panique totale"},"cards":[{"title":"Le silence menace un besoin précis, pas ton ego","advice":"Un silence de quelques secondes entre inconnus active une inquiétude sociale spécifique, le besoin d'appartenance, pas un jugement réel sur toi. Le comprendre suffit souvent à baisser la panique.","sourceId":"a0000000-0000-0000-0000-000000000005"},{"title":"Le seuil, c'est environ 4 secondes","advice":"En dessous, un silence passe totalement inaperçu. Compter mentalement \"un, deux, trois\" avant de réagir t'évite de combler un vide qui, pour l'autre, n'existait pas encore.","sourceId":"a0000000-0000-0000-0000-000000000005"},{"title":"La relance par \"callback\"","advice":"Reviens sur un détail mentionné 2 minutes plus tôt (\"Tu disais tout à l'heure que...\") : c'est la relance la plus naturelle, elle ne sort pas de nulle part.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Un silence n'est pas toujours à combler","advice":"Une fois la relation installée, le silence cesse d'être perçu négativement. Il peut même devenir un signe de confort mutuel : le stade de la relation explique cette gêne avec un inconnu, pas ta compétence sociale.","sourceId":"a0000000-0000-0000-0000-000000000006"},{"title":"Récap","advice":"Le silence menace un besoin précis (pas ta valeur), le seuil de gêne réel est plus court que tu crois compenser, le callback est ta relance la plus fiable.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"Un silence de 5 secondes vient de s'installer lors d'un café avec une connaissance récente. Laquelle de ces relances est la plus efficace ?","options":[{"text":"Revenir sur ce qu'elle a dit 5 minutes plus tôt et poser une question dessus","feedback":"C'est la plus efficace : elle relance un fil déjà engagé plutôt que d'ouvrir un sujet à froid ou de pointer le malaise, ce qui le renforcerait.","isBest":true},{"text":"Commenter la météo pour combler immédiatement","feedback":"Ouvrir un sujet totalement nouveau à froid est moins naturel qu'une relance sur un fil déjà engagé dans la conversation.","isBest":false},{"text":"S'excuser d'avoir \"fait un blanc\"","feedback":"Pointer le malaise à voix haute a tendance à le renforcer plutôt qu'à le désamorcer.","isBest":false}]},"personalization":{"condition":">=7","reorderCardIndexFirst":0}}$json$::jsonb, $json${"hook":"You're one-on-one, the conversation slows, then stops. Three seconds pass. Your heart races, you desperately search for something, anything, to say. This discomfort has a precise explanation: researchers measured, down to a tenth of a second, exactly when a silence starts to hurt, and why.","diagnostic":{"kind":"slider","question":"How uncomfortable does a few seconds of silence in a conversation make you?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"Total panic"},"cards":[{"title":"The silence threatens a specific need, not your ego","advice":"A few seconds of silence between strangers activates a specific social worry, the need to belong, not a real judgment of you. Understanding that is often enough to lower the panic.","sourceId":"a0000000-0000-0000-0000-000000000005"},{"title":"The threshold is about 4 seconds","advice":"Below that, a silence goes completely unnoticed. Mentally counting \"one, two, three\" before reacting keeps you from filling a gap that, for the other person, didn't exist yet.","sourceId":"a0000000-0000-0000-0000-000000000005"},{"title":"The \"callback\" follow-up","advice":"Bring up a detail mentioned 2 minutes earlier (\"You were saying earlier that...\"): it's the most natural way back in, it doesn't come out of nowhere.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"A silence isn't always something to fill","advice":"Once the relationship is established, silence stops being read negatively. It can even become a sign of mutual comfort: it's the stage of the relationship that explains this discomfort with a stranger, not your social skill.","sourceId":"a0000000-0000-0000-0000-000000000006"},{"title":"Recap","advice":"Silence threatens a specific need (not your worth), the real discomfort threshold is shorter than you think you need to fill, the callback is your most reliable way back in.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"A 5-second silence just settled in during coffee with a recent acquaintance. Which of these follow-ups works best?","options":[{"text":"Bring up something she said 5 minutes earlier and ask about it","feedback":"It's the most effective: it revives a thread already underway rather than opening a topic cold or pointing out the discomfort, which would only reinforce it.","isBest":true},{"text":"Comment on the weather to fill the gap immediately","feedback":"Opening a totally new topic cold is less natural than picking up a thread already underway in the conversation.","isBest":false},{"text":"Apologize for \"going blank\"","feedback":"Pointing out the discomfort out loud tends to reinforce it rather than defuse it.","isBest":false}]},"personalization":{"condition":">=7","reorderCardIndexFirst":0}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000003', 'sortir-conversation', $$Sortir poliment d'une conversation$$, $$Politely leaving a conversation$$, 3, ARRAY['conversation']::text[], false, 1, null, 'premium', $json${"hook":"Ça fait dix minutes que tu cherches une porte de sortie polie, sans la trouver. Tu culpabilises à l'idée de \"vexer\" l'autre en partant. Une étude a suivi des milliers de conversations réelles pour répondre à une question simple : qui, vraiment, a envie que ça s'arrête ?","diagnostic":{"kind":"slider","question":"À quel point te sens-tu coupable quand tu veux mettre fin à une conversation ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Énormément"},"cards":[{"title":"Tu n'es presque jamais seul à vouloir partir","advice":"Dans une étude sur des milliers de conversations, les deux personnes se sont mises d'accord sur le bon moment pour arrêter dans moins de 2% des cas. Et près d'une conversation sur trois s'arrête trop tard aux yeux d'au moins une des deux personnes.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"Personne ne suit ça d'aussi près que toi","advice":"Les chercheurs l'ont observé : chacun garde secrète son envie de partir. L'autre ne \"compte\" pas tes signaux de sortie, il ne les cherche probablement même pas.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"La sortie en 3 temps","advice":"Une observation (\"Il faut que j'y aille\"), une raison courte sans sur-justification, une phrase chaleureuse (\"Ravi d'avoir discuté !\"). Pas besoin de plus.","sourceId":"a0000000-0000-0000-0000-000000000008"},{"title":"Le mythe de la sortie parfaite","advice":"Il n'y a pas de moment \"juste\" universel. La recherche montre que ce moment n'existe même pas objectivement, chacun le perçoit différemment. Viser une sortie \"correcte\" plutôt que \"parfaite\" suffit.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"Récap","advice":"Statistiquement, l'autre a probablement aussi envie que ça se termine ; une sortie en 3 temps suffit ; il n'y a pas de \"bon moment\" objectif à chercher.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Tu es coincé dans une conversation depuis 15 minutes lors d'un afterwork, tu dois partir dans 5 minutes. Qu'est-ce que tu dirais pour sortir poliment ?","examples":["\"Il faut que j'y aille, j'ai un truc tôt demain. Ravi d'avoir discuté avec toi !\"","\"Je vais aller saluer d'autres personnes avant de partir, à bientôt !\"","\"Ça a été un plaisir de papoter, je file mais on se recroise vite.\""]}}$json$::jsonb, $json${"hook":"You've spent ten minutes looking for a polite way out, and haven't found one. You feel guilty at the idea of \"offending\" the other person by leaving. A study tracked thousands of real conversations to answer a simple question: who, really, wants it to end?","diagnostic":{"kind":"slider","question":"How guilty do you feel when you want to end a conversation?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"Enormously"},"cards":[{"title":"You're almost never the only one who wants to leave","advice":"In a study of thousands of conversations, both people agreed on the right moment to stop in fewer than 2% of cases. And nearly one conversation in three ends too late in the eyes of at least one of the two people.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"No one is tracking this as closely as you are","advice":"Researchers observed it directly: everyone keeps their wish to leave secret. The other person isn't \"counting\" your exit signals, they're probably not even looking for them.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"The 3-step exit","advice":"An observation (\"I have to get going\"), a short reason without over-justifying, a warm closing line (\"Great talking to you!\"). Nothing more is needed.","sourceId":"a0000000-0000-0000-0000-000000000008"},{"title":"The myth of the perfect exit","advice":"There's no universal \"right\" moment. Research shows that moment doesn't even exist objectively, everyone perceives it differently. Aiming for a \"decent\" exit rather than a \"perfect\" one is enough.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"Recap","advice":"Statistically, the other person probably also wants it to end; a 3-step exit is enough; there's no objective \"right moment\" to look for.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"You've been stuck in a conversation for 15 minutes at an afterwork event, and you need to leave in 5 minutes. What would you say to leave politely?","examples":["\"I have to get going, early start tomorrow. Great talking to you!\"","\"I'm going to go say hi to some other people before I head out, see you soon!\"","\"This was really nice, I'm off, but let's catch up again soon.\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000004', 'recuperer-energie', $$Récupérer son énergie après un événement social$$, $$Recovering your energy after a social event$$, 4, ARRAY['recuperation', 'energie']::text[], false, 1, null, 'premium', $json${"hook":"L'événement est fini depuis une heure. Tu es rentré, la porte est fermée, et pourtant tu te sens vidé, presque groggy, incapable d'enchaîner sur autre chose. Cette fatigue n'a rien de mental : elle se mesure dans ton système nerveux, et une méthode précise existe pour la récupérer plus vite.","diagnostic":{"kind":"slider","question":"Sur une échelle de 1 à 10, à quel point te sens-tu épuisé socialement en ce moment ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Complètement vidé"},"cards":[{"title":"Ton système nerveux, pas ton caractère","advice":"Les personnes introverties partent d'un niveau d'éveil cérébral déjà plus élevé au repos ; un événement social les fait donc franchir plus vite leur seuil optimal, ce qui déclenche la fatigue. C'est physiologique, pas un manque de volonté.","sourceId":"a0000000-0000-0000-0000-000000000009"},{"title":"La \"niche restauratrice\"","advice":"Après avoir agi \"hors de son tempérament naturel\" (sourire, faire la conversation, rester stimulé), le cerveau a besoin d'un espace qui correspond à sa nature de base pour récupérer : silence, stimulation réduite, seul.","sourceId":"a0000000-0000-0000-0000-000000000010"},{"title":"Négocie ta récupération à l'avance","advice":"Prévenir ton entourage (\"j'ai besoin d'une heure seul en rentrant\") avant même l'événement, plutôt que de te justifier après coup, réduit la culpabilité et protège vraiment ce temps.","sourceId":"a0000000-0000-0000-0000-000000000010"},{"title":"Recharge active, pas juste passive","advice":"Toute \"pause\" ne recharge pas de la même façon : une activité à faible stimulation sensorielle (silence, nature, lecture) recharge mieux qu'une activité qui continue de solliciter l'attention (réseaux sociaux, série captivante).","sourceId":"a0000000-0000-0000-0000-000000000009"},{"title":"Récap","advice":"La fatigue post-événement est physiologique, pas un défaut ; ta niche restauratrice doit être planifiée, pas improvisée ; toutes les pauses ne se valent pas.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Qu'est-ce que tu pourrais mettre en place dans les 2 heures après ton prochain événement social pour récupérer efficacement ?","examples":["Silence total et lumière tamisée pendant 30 minutes en rentrant, sans écran.","Une promenade seul, sans podcast ni musique, pour laisser l'esprit se vider.","Un moment de lecture plutôt qu'une série ou les réseaux sociaux."]}}$json$::jsonb, $json${"hook":"The event ended an hour ago. You're home, the door is closed, and yet you feel drained, almost groggy, unable to move on to anything else. This fatigue is nothing mental: it can be measured in your nervous system, and there's a precise method for recovering from it faster.","diagnostic":{"kind":"slider","question":"On a scale of 1 to 10, how socially exhausted do you feel right now?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"Completely drained"},"cards":[{"title":"Your nervous system, not your character","advice":"Introverted people start from an already-higher baseline level of cortical arousal at rest; a social event pushes them past their optimal threshold faster, which triggers the fatigue. It's physiological, not a lack of willpower.","sourceId":"a0000000-0000-0000-0000-000000000009"},{"title":"The \"restorative niche\"","advice":"After acting \"out of character\" (smiling, making conversation, staying stimulated), the brain needs a space that matches its baseline nature to recover: quiet, reduced stimulation, alone.","sourceId":"a0000000-0000-0000-0000-000000000010"},{"title":"Negotiate your recovery in advance","advice":"Telling the people around you (\"I need an hour alone when I get back\") before the event even happens, rather than justifying yourself afterward, lowers the guilt and actually protects that time.","sourceId":"a0000000-0000-0000-0000-000000000010"},{"title":"Active recharge, not just passive","advice":"Not every \"break\" recharges the same way: a low-sensory-stimulation activity (silence, nature, reading) recharges better than one that keeps demanding attention (social media, a gripping show).","sourceId":"a0000000-0000-0000-0000-000000000009"},{"title":"Recap","advice":"Post-event fatigue is physiological, not a flaw; your restorative niche needs to be planned, not improvised; not all breaks are equal.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"What could you put in place in the 2 hours after your next social event to recover effectively?","examples":["Total silence and dim lighting for 30 minutes when you get home, no screens.","A walk alone, no podcast or music, to let your mind empty out.","Reading instead of a show or social media."]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000005', 'gerer-anxiete-avant-evenement', $$Gérer l'anxiété avant un événement$$, $$Managing anxiety before an event$$, 5, ARRAY['anxiete']::text[], false, 1, null, 'premium', $json${"hook":"L'événement est dans trois jours. Tu y penses déjà en boucle : et si je ne trouve rien à dire, et si c'est gênant, et si... L'anxiété que tu ressens là, maintenant, avant même que rien ne se soit passé, a un nom précis en psychologie clinique. C'est souvent elle, pas l'événement lui-même, qui fait le plus de dégâts.","diagnostic":{"kind":"slider-double","questions":["Sur 10, à quel point es-tu anxieux à l'idée de cet événement, là, maintenant ?","D'après toi, sur 10, à quel point l'événement se passera-t-il mal réellement ?"]},"cards":[{"title":"Le vrai coupable : la rumination \"avant\"","advice":"Le modèle de référence en thérapie cognitivo-comportementale de l'anxiété sociale identifie la rumination anticipatoire (repasser en boucle des scénarios négatifs avant l'événement) comme un moteur central qui entretient l'anxiété, indépendamment de ce qui se passe réellement.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Repérer la pensée automatique","advice":"\"Je vais être gênant\", \"personne ne voudra me parler\" : ce sont des prédictions, pas des faits. Les nommer comme telles (\"c'est une pensée, pas une certitude\") réduit déjà leur emprise.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Arrête de \"t'entraîner\" en boucle","advice":"Le même modèle identifie les comportements de sécurité (répéter mentalement ce que tu vas dire, éviter le regard, sur-préparer) comme des stratégies qui, paradoxalement, entretiennent l'anxiété au lieu de la réduire.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Compare après coup","advice":"Note ta prédiction avant l'événement, puis reviens dessus après : l'écart entre ce que tu craignais et ce qui s'est vraiment passé est souvent l'argument le plus convaincant contre l'anxiété anticipatoire, plus que n'importe quel conseil.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Récap","advice":"L'anxiété \"avant\" vient surtout de la rumination, pas de l'événement ; repère tes pensées automatiques ; arrête de sur-préparer ; compare prédiction et réalité après coup.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Écris la pensée qui tourne en boucle avant cet événement.","followUp":"Maintenant, reformule-la comme une prédiction testable plutôt qu'un fait (\"Je prédis que... mais je ne le sais pas encore\")."}}$json$::jsonb, $json${"hook":"The event is in three days. You're already thinking about it on a loop: what if I have nothing to say, what if it's awkward, what if... The anxiety you feel right now, before anything has even happened, has a precise name in clinical psychology. It's often this, not the event itself, that does the most damage.","diagnostic":{"kind":"slider-double","questions":["Out of 10, how anxious are you about this event, right now?","In your opinion, out of 10, how badly will the event actually go?"]},"cards":[{"title":"The real culprit: \"before\" rumination","advice":"The reference model in cognitive behavioral therapy for social anxiety identifies anticipatory rumination (replaying negative scenarios on a loop before the event) as a central driver that sustains anxiety, regardless of what actually happens.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Spot the automatic thought","advice":"\"I'm going to be awkward,\" \"no one will want to talk to me\": these are predictions, not facts. Naming them as such (\"this is a thought, not a certainty\") already reduces their grip.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Stop \"rehearsing\" on a loop","advice":"The same model identifies safety behaviors (mentally rehearsing what you'll say, avoiding eye contact, over-preparing) as strategies that, paradoxically, sustain anxiety instead of reducing it.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Compare afterward","advice":"Write down your prediction before the event, then revisit it afterward: the gap between what you feared and what actually happened is often the most convincing argument against anticipatory anxiety, more than any advice.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Recap","advice":"\"Before\" anxiety mostly comes from rumination, not the event; spot your automatic thoughts; stop over-preparing; compare prediction and reality afterward.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Write down the thought that's looping before this event.","followUp":"Now rephrase it as a testable prediction rather than a fact (\"I predict that... but I don't know that yet\")."}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000006', 'repondre-blanc-mental', $$Répondre lors d'un blanc mental$$, $$Responding during a mental blank$$, 6, ARRAY['conversation']::text[], false, 1, null, 'premium', $json${"hook":"Quelqu'un vient de te poser une question. Et là, rien. Ta tête est vide, les secondes s'étirent, tu sens la panique monter. Bonne nouvelle : répondre \"à chaud\" sans texte préparé est une compétence spécifique, et elle s'entraîne avec des méthodes déjà testées.","diagnostic":{"kind":"slider","question":"À quel point la peur du blanc mental t'empêche-t-elle de te lancer dans une conversation ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Ça me bloque complètement"},"cards":[{"title":"Vise \"assez bien\", pas \"parfait\"","advice":"Chercher la réponse idéale sature ta charge mentale et bloque encore plus. Viser une réponse \"suffisante\" libère de l'espace cognitif pour parler, tout simplement.","sourceId":"a0000000-0000-0000-0000-000000000012"},{"title":"L'improvisation, ça s'entraîne (et ça marche), avec preuves","advice":"Une expérience contrôlée a montré que des personnes formées à l'improvisation théâtrale, même sur une courte durée, développaient une meilleure tolérance à l'incertitude et un mieux-être affectif mesurable, comparées à un groupe témoin.","sourceId":"a0000000-0000-0000-0000-000000000013"},{"title":"Dis le blanc, ne le cache pas","advice":"Un principe central de l'improvisation : accepter ce qui arrive plutôt que lutter contre. Dire simplement \"attends, laisse-moi réfléchir une seconde\" est plus fluide, et plus humain, qu'un silence figé suivi de panique.","sourceId":"a0000000-0000-0000-0000-000000000013"},{"title":"Des phrases-pont à avoir en réserve","advice":"\"C'est une bonne question, laisse-moi y réfléchir\", \"ça me fait penser à...\", \"en fait je n'y avais pas pensé comme ça\" : mémoriser 2-3 phrases-pont te donne du temps sans silence gênant.","sourceId":"a0000000-0000-0000-0000-000000000012"},{"title":"Récap","advice":"Vise \"assez bien\" plutôt que parfait, entraîne-toi à l'incertitude comme une compétence, verbalise le blanc au lieu de le cacher, garde des phrases-pont en réserve.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"On te demande \"Et toi, tu en penses quoi ?\" sur un sujet que tu ne maîtrises pas du tout. Ta tête est vide. Qu'est-ce que tu dirais ?","examples":["\"C'est une bonne question, laisse-moi y réfléchir une seconde.\"","\"Ça me fait penser à... en fait je n'y avais pas pensé comme ça avant.\"","\"Honnêtement je ne connais pas trop le sujet, qu'est-ce que toi tu en penses ?\""]}}$json$::jsonb, $json${"hook":"Someone just asked you a question. And nothing. Your mind is empty, the seconds stretch out, you feel the panic rising. Good news: responding \"on the spot\" without a prepared script is a specific skill, and it can be trained with methods that are already tested.","diagnostic":{"kind":"slider","question":"How much does the fear of going blank stop you from starting a conversation?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"It blocks me completely"},"cards":[{"title":"Aim for \"good enough,\" not \"perfect\"","advice":"Searching for the ideal answer overloads your mental bandwidth and blocks you even more. Aiming for a \"sufficient\" answer frees up cognitive space to simply speak.","sourceId":"a0000000-0000-0000-0000-000000000012"},{"title":"Improv can be trained (and it works), with evidence","advice":"A controlled experiment showed that people trained in improv theater, even briefly, developed better tolerance for uncertainty and measurably better emotional well-being, compared to a control group.","sourceId":"a0000000-0000-0000-0000-000000000013"},{"title":"Say the blank, don't hide it","advice":"A core principle of improv: accept what's happening instead of fighting it. Simply saying \"wait, let me think for a second\" is smoother, and more human, than a frozen silence followed by panic.","sourceId":"a0000000-0000-0000-0000-000000000013"},{"title":"Keep bridge phrases in reserve","advice":"\"That's a good question, let me think about it,\" \"that makes me think of...,\" \"actually I hadn't thought about it that way\": memorizing 2-3 bridge phrases buys you time without an awkward silence.","sourceId":"a0000000-0000-0000-0000-000000000012"},{"title":"Recap","advice":"Aim for \"good enough\" rather than perfect, train uncertainty like a skill, say the blank out loud instead of hiding it, keep bridge phrases in reserve.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Someone asks \"So what do you think?\" about a topic you don't know at all. Your mind is blank. What would you say?","examples":["\"That's a good question, let me think about it for a second.\"","\"That makes me think of... actually I hadn't thought about it that way before.\"","\"Honestly I don't know much about this, what do you think?\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000007', 'repas-reunions-famille', $$Gérer les repas et réunions de famille$$, $$Handling family meals and gatherings$$, 7, ARRAY['famille', 'repas']::text[], false, 1, null, 'premium', $json${"hook":"Le repas commence à peine que ton oncle lance déjà une remarque sur ta vie que tu redoutais. Tu sens ta mâchoire se serrer. Ce qui va se passer dans les 3 prochaines minutes est, statistiquement, presque entièrement prévisible d'après des décennies de recherche sur la façon dont les tensions démarrent et dégénèrent, ou non.","diagnostic":{"kind":"slider","question":"À quel point redoutes-tu qu'un sujet précis revienne à la prochaine réunion de famille ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"J'y pense déjà en boucle"},"cards":[{"title":"Les 3 premières minutes comptent presque tout","advice":"Une recherche menée sur des décennies de discussions filmées montre que la façon dont un échange démarre prédit avec une précision très élevée comment il va se terminer. Si un sujet démarre déjà sur un ton accusateur, désamorce tout de suite plutôt que d'entrer dans le fond.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"La tentative de réparation","advice":"Les familles qui gèrent bien les tensions ne cherchent pas à éviter tout désaccord. Elles savent le désamorcer en cours de route, par une phrase, un geste, ou même une pointe d'humour, avant que ça escalade.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"Change de sujet sans confrontation directe","advice":"Une redirection neutre (\"Tiens, en parlant de ça, tu as vu que...\") détourne le fil sans déclarer ouvertement que tu refuses le sujet. C'est une technique de désescalade simple, éprouvée en pratique.","sourceId":"a0000000-0000-0000-0000-000000000015"},{"title":"Tu n'as pas à gagner le débat","advice":"Au repas de famille, le but est de préserver la relation, pas d'avoir raison. Lâcher le besoin de convaincre change complètement le niveau de tension.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"Récap","advice":"Désamorce dès les premières secondes, utilise une tentative de réparation avant l'escalade, redirige sans confronter, laisse tomber le besoin d'avoir raison.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"Ta tante fait une remarque désobligeante sur un de tes choix de vie à table. Laquelle de ces réponses est la plus efficace pour désamorcer sans envenimer ?","options":[{"text":"Répondre avec humour puis rediriger la conversation vers un autre sujet","feedback":"Désamorce sans escalade ni sacrifice de dignité : c'est une vraie tentative de réparation.","isBest":true},{"text":"Expliquer en détail et avec passion pourquoi elle a tort","feedback":"Alimente le conflit dès les premières secondes plutôt que de le désamorcer.","isBest":false},{"text":"Ignorer complètement et changer de visage","feedback":"Peut être perçu comme un signal de tension non résolu plutôt qu'une vraie désescalade.","isBest":false}]}}$json$::jsonb, $json${"hook":"The meal has barely started and your uncle is already making the comment about your life you were dreading. You feel your jaw tighten. What's going to happen in the next 3 minutes is, statistically, almost entirely predictable based on decades of research on how tensions start, and whether or not they escalate.","diagnostic":{"kind":"slider","question":"How much do you dread a specific topic coming up at the next family gathering?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"I'm already thinking about it on a loop"},"cards":[{"title":"The first 3 minutes decide almost everything","advice":"Research based on decades of filmed discussions shows that how an exchange starts predicts, with very high accuracy, how it will end. If a topic starts on an accusatory tone, defuse it right away instead of engaging with the substance.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"The repair attempt","advice":"Families who handle tension well don't try to avoid all disagreement. They know how to defuse it along the way, with a line, a gesture, or even a touch of humor, before it escalates.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"Change the subject without direct confrontation","advice":"A neutral redirection (\"Oh, speaking of that, did you see...\") diverts the thread without openly declaring that you're refusing the topic. It's a simple de-escalation technique, proven in practice.","sourceId":"a0000000-0000-0000-0000-000000000015"},{"title":"You don't have to win the argument","advice":"At a family meal, the goal is to preserve the relationship, not to be right. Letting go of the need to convince completely changes the level of tension.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"Recap","advice":"Defuse from the first seconds, use a repair attempt before it escalates, redirect without confronting, let go of the need to be right.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"Your aunt makes a snide remark about one of your life choices at the table. Which of these responses best defuses it without making it worse?","options":[{"text":"Respond with humor and then redirect the conversation to another topic","feedback":"Defuses without escalating or sacrificing your dignity: it's a genuine repair attempt.","isBest":true},{"text":"Explain in detail and with passion why she's wrong","feedback":"Fuels the conflict from the first seconds instead of defusing it.","isBest":false},{"text":"Ignore it completely and change your expression","feedback":"Can be read as a sign of unresolved tension rather than a real de-escalation.","isBest":false}]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000008', 'amis-age-adulte', $$Se faire des amis à l'âge adulte$$, $$Making friends as an adult$$, 8, ARRAY['amitie']::text[], false, 1, null, 'premium', $json${"hook":"Tu regardes tes contacts : des collègues, des connaissances, personne à qui envoyer un message \"juste pour parler\". Se faire des amis à l'âge adulte semble impossible. Pourtant, une étude a mesuré précisément ce qu'il faut, en heures, pour transformer un inconnu en ami. La réponse est rassurante : le temps cumulé compte plus que la chance.","diagnostic":{"kind":"slider","question":"À quel point te sens-tu seul socialement en ce moment ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Énormément"},"cards":[{"title":"Ce n'est pas toi, c'est le manque d'heures","advice":"Il faut environ 40 à 60 heures passées ensemble pour devenir des amis \"occasionnels\", 80 à 100 heures pour devenir vraiment amis, et plus de 200 heures pour un ami proche. L'amitié à l'âge adulte n'a rien de magique : elle s'accumule.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"La répétition compte plus que la profondeur, au début","advice":"Dans les premières heures, ce sont les interactions répétées, même courtes et légères, qui font avancer la relation, pas une seule conversation \"profonde\".","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Le travail ne compte presque pas","advice":"Les heures passées à travailler ensemble comptent beaucoup moins que les heures de loisirs partagés ou de simples moments informels. Un collègue avec qui tu ris à la pause compte plus, pour l'amitié, qu'un projet commun.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Vise la récurrence, pas l'événement unique","advice":"Rejoindre une activité hebdomadaire ou mensuelle (club, sport, cours) accumule les heures nécessaires bien plus vite qu'une série de rencontres isolées, même nombreuses.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Récap","advice":"L'amitié adulte est une question d'heures cumulées, pas de chance ; privilégie la récurrence à l'événement unique ; le contexte informel compte plus que le contexte professionnel.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"Identifie une activité récurrente (hebdomadaire ou mensuelle) que tu pourrais rejoindre pour accumuler du temps avec les mêmes personnes.","examples":["Un cours collectif (sport, langue, art) qui revient chaque semaine.","Un club ou une association liée à un centre d'intérêt existant.","Un groupe de jeu ou une activité régulière avec des collègues ou connaissances."]}}$json$::jsonb, $json${"hook":"You look at your contacts: coworkers, acquaintances, no one to text \"just to talk.\" Making friends as an adult seems impossible. And yet, a study precisely measured how many hours it takes to turn a stranger into a friend. The answer is reassuring: cumulative time matters more than luck.","diagnostic":{"kind":"slider","question":"How socially lonely do you feel right now?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"Enormously"},"cards":[{"title":"It's not you, it's the missing hours","advice":"It takes about 40 to 60 hours spent together to become \"casual\" friends, 80 to 100 hours to become real friends, and more than 200 hours for a close friend. Adult friendship has nothing magic about it: it accumulates.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Repetition matters more than depth, at first","advice":"In the early hours, it's repeated interactions, even short and light ones, that move the relationship forward, not a single \"deep\" conversation.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Work barely counts","advice":"Hours spent working together contribute much less than hours of shared leisure or simple informal moments. A coworker you laugh with at break counts more, for friendship, than a shared project.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Aim for recurrence, not a one-off","advice":"Joining a weekly or monthly activity (club, sport, class) accumulates the necessary hours much faster than a series of isolated meetings, even many of them.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Recap","advice":"Adult friendship is a matter of accumulated hours, not luck; favor recurrence over one-off events; informal settings count more than professional ones.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"Identify a recurring activity (weekly or monthly) you could join to build up time with the same people.","examples":["A group class (sport, language, art) that happens every week.","A club or association tied to an interest you already have.","A regular game group or activity with coworkers or acquaintances."]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000009', 'small-talk-travail', $$Gérer les petites conversations au travail (small talk)$$, $$Handling small talk at work$$, 9, ARRAY['travail']::text[], false, 1, null, 'premium', $json${"hook":"La machine à café. Encore. Tu sens déjà venir la question \"ça va, ce week-end ?\" et l'échange creux qui suivra. Le small talk te semble être une perte de temps et d'énergie. Pourtant, une étude menée sur des centaines d'employés a mesuré ce qu'il t'apporte vraiment, au-delà de l'apparence.","diagnostic":{"kind":"slider","question":"À quel point le small talk au travail te semble-t-il une perte de temps et d'énergie ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Complètement"},"cards":[{"title":"Le small talk n'est pas superficiel, il finance ta journée","advice":"Une étude menée auprès de plus de 150 employés a montré que le small talk quotidien augmente les émotions positives et le sentiment de bien-être en fin de journée, et rend plus enclin à aider ses collègues.","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"Mais il a un vrai coût cognitif","advice":"La même étude montre un effet double, \"stimulant mais distrayant\" : le small talk peut couper ta concentration. La solution n'est pas de l'éviter, mais de le cadrer dans le temps (2-3 minutes suffisent).","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"C'est un rituel, pas un test","advice":"Le fait même de l'échange compte plus que la profondeur ou l'originalité du contenu, comme un rituel social. Ça enlève la pression d'être \"intéressant\".","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"FORD, version bureau","advice":"Reprends la méthode FORD du cours 1, mais évite \"Famille\" (trop personnel en contexte pro) et privilégie Occupation et loisirs neutres : \"Tu avances sur quoi en ce moment ?\", \"Tu as vu un bon film récemment ?\".","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Récap","advice":"Le small talk améliore réellement ton bien-être au travail, cadre-le dans le temps pour limiter son coût cognitif, et traite-le comme un rituel plutôt qu'un test de personnalité.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Tu croises un collègue à la machine à café. Qu'est-ce que tu dirais pour lancer une conversation courte et naturelle ?","examples":["\"Tu avances sur quoi en ce moment ?\"","\"Tu as vu un bon film ou une série récemment ?\"","\"Cette machine à café est capricieuse aujourd'hui, hein ?\" (commentaire de contexte)"]}}$json$::jsonb, $json${"hook":"The coffee machine. Again. You can already feel the \"how was your weekend?\" question coming, and the hollow exchange that follows. Small talk feels like a waste of time and energy to you. And yet, a study of hundreds of employees measured what it actually gives you, beyond appearances.","diagnostic":{"kind":"slider","question":"How much does small talk at work feel like a waste of time and energy to you?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"Completely"},"cards":[{"title":"Small talk isn't superficial, it funds your day","advice":"A study of more than 150 employees showed that daily small talk increases positive emotions and end-of-day well-being, and makes people more likely to help their coworkers.","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"But it has a real cognitive cost","advice":"The same study shows a double effect, \"uplifting yet distracting\": small talk can break your focus. The solution isn't to avoid it, but to keep it time-boxed (2-3 minutes is enough).","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"It's a ritual, not a test","advice":"The exchange itself matters more than the depth or originality of the content, like a social ritual. That takes the pressure off having to be \"interesting.\"","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"FORD, office edition","advice":"Reuse the FORD method from course 1, but skip \"Family\" (too personal in a work setting) and favor Occupation and neutral leisure: \"What are you working on these days?\", \"Seen any good movies lately?\"","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Recap","advice":"Small talk genuinely improves your well-being at work, keep it time-boxed to limit its cognitive cost, and treat it as a ritual rather than a personality test.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"You run into a coworker at the coffee machine. What would you say to start a short, natural conversation?","examples":["\"What are you working on these days?\"","\"Seen any good movies or shows lately?\"","\"This machine is being temperamental today, huh?\" (context comment)"]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000010', 'poser-limite-sociale', $$Poser une limite sociale sans culpabiliser$$, $$Setting a social boundary without guilt$$, 10, ARRAY['limites']::text[], false, 1, null, 'premium', $json${"hook":"Tu viens de dire \"oui\" à une sollicitation dont tu n'avais pas envie. Encore une fois. La boule au ventre s'installe déjà. Poser une limite semble impossible sans se sentir égoïste, pourtant une synthèse de plusieurs essais contrôlés montre que cette capacité s'entraîne, avec un effet mesurable.","diagnostic":{"kind":"slider","question":"À quel point te sens-tu coupable quand tu dis non à une sollicitation sociale ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Énormément"},"cards":[{"title":"Ça s'entraîne, avec des preuves","advice":"Une synthèse de 12 essais contrôlés randomisés portant sur plus de 500 personnes a montré que l'entraînement à l'affirmation de soi produit un effet réel et mesurable sur le comportement assertif et l'anxiété sociale.","sourceId":"a0000000-0000-0000-0000-000000000018"},{"title":"La formule DESC","advice":"Décris les faits, Exprime ce que tu ressens, Spécifie ce que tu proposes, précise les Conséquences positives. Une structure simple pour poser une limite sans agressivité ni justification excessive.","sourceId":"a0000000-0000-0000-0000-000000000019"},{"title":"Dire non sans se justifier pendant 5 minutes","advice":"Une phrase courte suffit : \"Je ne suis pas disponible ce soir-là.\" Sur-expliquer donne à l'autre plus de prise pour négocier ta limite.","sourceId":"a0000000-0000-0000-0000-000000000020"},{"title":"La culpabilité n'est pas un signal d'erreur","advice":"La gêne initiale après avoir posé une limite est normale, et elle diminue avec la pratique, comme le montre l'effet d'entraînement de la méta-analyse. Ce n'est pas un signe que tu as mal agi.","sourceId":"a0000000-0000-0000-0000-000000000018"},{"title":"Récap","advice":"Poser des limites est une compétence entraînable et prouvée ; utilise DESC ; une phrase courte suffit ; la culpabilité initiale est normale et passagère.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"On te sollicite pour quelque chose dont tu n'as pas envie. Écris ta réponse en utilisant la structure DESC.","examples":["\"Ce week-end je suis déjà pris (D). Ça me tient à cœur de pouvoir souffler un peu (E). Est-ce qu'on peut se voir la semaine d'après à la place (S) ? On profitera d'avoir plus de temps (C).\"","\"Je ne suis pas disponible ce soir-là (D). Je préfère être honnête plutôt que d'annuler après (E). Je te propose une autre date (S), comme ça on est sûrs d'en profiter vraiment (C).\""]}}$json$::jsonb, $json${"hook":"You just said \"yes\" to something you didn't want to do. Again. The knot in your stomach is already forming. Setting a boundary seems impossible without feeling selfish, yet a review of several controlled trials shows that this ability can be trained, with a measurable effect.","diagnostic":{"kind":"slider","question":"How guilty do you feel when you say no to a social request?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"Enormously"},"cards":[{"title":"It can be trained, with evidence","advice":"A review of 12 randomized controlled trials covering more than 500 people showed that assertiveness training produces a real, measurable effect on assertive behavior and social anxiety.","sourceId":"a0000000-0000-0000-0000-000000000018"},{"title":"The DESC formula","advice":"Describe the facts, Express what you feel, Specify what you're proposing, state the positive Consequences. A simple structure for setting a boundary without aggression or excessive justification.","sourceId":"a0000000-0000-0000-0000-000000000019"},{"title":"Say no without justifying yourself for 5 minutes","advice":"A short sentence is enough: \"I'm not available that evening.\" Over-explaining gives the other person more room to negotiate your boundary.","sourceId":"a0000000-0000-0000-0000-000000000020"},{"title":"Guilt isn't a sign you did something wrong","advice":"The initial discomfort after setting a boundary is normal, and it decreases with practice, as shown by the training effect in the meta-analysis. It's not a sign that you acted wrongly.","sourceId":"a0000000-0000-0000-0000-000000000018"},{"title":"Recap","advice":"Setting boundaries is a trainable, proven skill; use DESC; a short sentence is enough; initial guilt is normal and temporary.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"You're asked to do something you don't want to do. Write your response using the DESC structure.","examples":["\"I'm already booked this weekend (D). It matters to me to get some real downtime (E). Could we meet the following week instead (S)? We'll have more time to enjoy it (C).\"","\"I'm not available that evening (D). I'd rather be upfront than cancel later (E). I'll suggest another date (S), so we can actually make the most of it (C).\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000011', 'rejoindre-groupe', $$Rejoindre un groupe déjà en pleine conversation$$, $$Joining a group already deep in conversation$$, 11, ARRAY['groupe', 'conversation']::text[], false, 1, null, 'premium', $json${"hook":"Tu arrives à une soirée. Un petit groupe discute déjà en cercle, animé, personne ne te voit. Tu restes planté à côté, sans savoir comment t'insérer sans avoir l'air d'interrompre. Ce moment précis a été étudié en détail par les chercheurs qui analysent comment les groupes s'organisent physiquement dans l'espace pendant une conversation.","diagnostic":{"kind":"slider","question":"À quel point te sens-tu à l'aise pour rejoindre un groupe déjà en pleine conversation ?","min":1,"max":10,"minLabel":"Terrifié","maxLabel":"Aucun souci"},"cards":[{"title":"Le cercle \"ouvert\" est une vraie invitation","advice":"Les groupes en conversation forment naturellement des arrangements spatiaux étudiés en sciences sociales : un cercle légèrement ouvert (pas complètement fermé) est une configuration reconnue comme une invitation implicite à s'approcher. Ce n'est pas un hasard si certains groupes te \"laissent de la place\" et d'autres non.","sourceId":"a0000000-0000-0000-0000-000000000025"},{"title":"Positionne-toi avant de parler","advice":"Approche-toi de l'ouverture du cercle, établis un contact visuel bref, hoche légèrement la tête. Laisse le groupe t'intégrer visuellement avant de dire quoi que ce soit : le positionnement précède la prise de parole.","sourceId":"a0000000-0000-0000-0000-000000000025"},{"title":"Écoute 10 secondes avant d'intervenir","advice":"Capter le sujet en cours évite l'entrée \"à l'aveugle\" qui casse la dynamique. Une fois le sujet identifié, ton entrée paraît naturelle plutôt que plaquée.","sourceId":"a0000000-0000-0000-0000-000000000026"},{"title":"Entre avec une question, pas une déclaration","advice":"Une question ouverte liée à ce qui vient d'être dit (\"Attends, comment vous en êtes arrivés là ?\") s'intègre plus naturellement qu'une remarque sans lien, et donne immédiatement la parole à quelqu'un du groupe.","sourceId":"a0000000-0000-0000-0000-000000000003"},{"title":"Récap","advice":"Repère un cercle ouvert plutôt que fermé, positionne-toi avant de parler, écoute quelques secondes pour capter le sujet, entre avec une question plutôt qu'une déclaration.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"Tu repères un groupe de 4 personnes en cercle légèrement ouvert lors d'un événement. Laquelle de ces approches est la plus efficace ?","options":[{"text":"S'approcher de l'ouverture, écouter quelques secondes, puis poser une question liée au sujet en cours","feedback":"Respecte à la fois le positionnement spatial et le fil de la conversation.","isBest":true},{"text":"S'approcher et se présenter directement à tout le groupe avant qu'ils aient fini leur phrase","feedback":"Casse la dynamique en cours.","isBest":false},{"text":"Attendre un silence total du groupe avant d'oser s'approcher","feedback":"Risque de ne jamais arriver, un silence total étant rare dans un groupe animé.","isBest":false}]}}$json$::jsonb, $json${"hook":"You arrive at a party. A small group is already talking in a circle, animated, no one sees you. You stand off to the side, not knowing how to join in without seeming to interrupt. This exact moment has been studied in detail by researchers who analyze how groups physically organize themselves in space during a conversation.","diagnostic":{"kind":"slider","question":"How comfortable do you feel joining a group already deep in conversation?","min":1,"max":10,"minLabel":"Terrified","maxLabel":"No problem at all"},"cards":[{"title":"An \"open\" circle is a real invitation","advice":"Groups in conversation naturally form spatial arrangements studied in social science: a slightly open circle (not fully closed) is a recognized configuration that acts as an implicit invitation to approach. It's not a coincidence that some groups \"leave you room\" and others don't.","sourceId":"a0000000-0000-0000-0000-000000000025"},{"title":"Position yourself before speaking","advice":"Move toward the opening in the circle, make brief eye contact, nod slightly. Let the group visually take you in before you say anything: positioning comes before speaking.","sourceId":"a0000000-0000-0000-0000-000000000025"},{"title":"Listen for 10 seconds before jumping in","advice":"Catching the current topic avoids a \"blind\" entry that breaks the dynamic. Once you've identified the topic, your entry feels natural instead of forced.","sourceId":"a0000000-0000-0000-0000-000000000026"},{"title":"Enter with a question, not a statement","advice":"An open question tied to what was just said (\"Wait, how did you get to that?\") fits in more naturally than an unrelated remark, and immediately hands the floor to someone in the group.","sourceId":"a0000000-0000-0000-0000-000000000003"},{"title":"Recap","advice":"Look for an open circle rather than a closed one, position yourself before speaking, listen a few seconds to catch the topic, enter with a question rather than a statement.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"You spot a group of 4 people in a slightly open circle at an event. Which of these approaches works best?","options":[{"text":"Move toward the opening, listen for a few seconds, then ask a question tied to the current topic","feedback":"Respects both the spatial positioning and the thread of the conversation.","isBest":true},{"text":"Walk up and introduce yourself to the whole group before they finish their sentence","feedback":"Breaks the ongoing dynamic.","isBest":false},{"text":"Wait for total silence from the group before daring to approach","feedback":"Risks never happening, since total silence is rare in an animated group.","isBest":false}]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000012', 'ecouter-vraiment', $$Écouter pour de vrai$$, $$Really listening$$, 12, ARRAY['ecoute']::text[], false, 1, null, 'premium', $json${"hook":"Un ami te raconte sa journée. Tu hoches la tête, mais une partie de toi est déjà en train de préparer ce que tu vas répondre. Tu n'écoutes qu'à moitié, et lui le sent probablement aussi. Plusieurs études en laboratoire ont mesuré ce qui change, chez la personne qui parle, quand elle se sent vraiment écoutée.","diagnostic":{"kind":"slider","question":"À quel point penses-tu déjà à ta réponse pendant que l'autre parle ?","min":1,"max":10,"minLabel":"Jamais","maxLabel":"Presque toujours"},"cards":[{"title":"Écouter change l'autre, pas juste toi","advice":"Une écoute de haute qualité (empathique, attentive, non jugeante) réduit mesurablement l'anxiété sociale et la défensivité de la personne qui parle, à travers plusieurs expériences contrôlées en laboratoire.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"Les 3 ingrédients d'une bonne écoute","advice":"Les chercheurs identifient trois composantes déterminantes : l'empathie, l'attention réelle, et l'absence de jugement. Retirer un seul des trois suffit à réduire l'effet.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"Ça te rend aussi plus appréciable, toi","advice":"Les personnes qui se sentent bien écoutées rapportent un sentiment de connexion plus fort envers leur interlocuteur. Bien écouter te profite aussi, ce n'est pas qu'un sacrifice social.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"La technique du reflet","advice":"Avant de répondre ou de donner ton avis, reformule brièvement ce que tu viens d'entendre (\"si je comprends bien, tu es surtout frustré par...\") : ça force une écoute réelle et montre à l'autre qu'il a été entendu.","sourceId":"a0000000-0000-0000-0000-000000000028"},{"title":"Récap","advice":"Une écoute de qualité réduit l'anxiété de celui qui parle, repose sur 3 ingrédients précis (empathie, attention, non-jugement), et te rend toi-même plus appréciable.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Un ami te partage un problème. Qu'est-ce que tu dirais juste après qu'il ait fini de parler ?","examples":["\"Si je comprends bien, ce qui te pèse le plus c'est... c'est ça ?\"","\"Ça a l'air vraiment difficile à vivre, merci de me le partager.\"","\"Attends, donc concrètement, ce qui t'embête c'est plutôt X ou Y ?\""]}}$json$::jsonb, $json${"hook":"A friend is telling you about their day. You nod, but part of you is already preparing what you're going to say back. You're only half listening, and they can probably tell too. Several lab studies have measured what changes, in the person speaking, when they feel truly listened to.","diagnostic":{"kind":"slider","question":"How much are you already thinking about your response while the other person is talking?","min":1,"max":10,"minLabel":"Never","maxLabel":"Almost always"},"cards":[{"title":"Listening changes the other person, not just you","advice":"High-quality listening (empathetic, attentive, non-judgmental) measurably reduces the social anxiety and defensiveness of the person speaking, across several controlled lab experiments.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"The 3 ingredients of good listening","advice":"Researchers identify three key components: empathy, real attention, and the absence of judgment. Removing just one of the three is enough to reduce the effect.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"It also makes you more likeable","advice":"People who feel well listened to report a stronger sense of connection to the person they're talking with. Listening well benefits you too, it's not just a social sacrifice.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"The reflection technique","advice":"Before responding or giving your opinion, briefly rephrase what you just heard (\"if I understand right, what's frustrating you most is...\"): it forces real listening and shows the other person they were heard.","sourceId":"a0000000-0000-0000-0000-000000000028"},{"title":"Recap","advice":"Quality listening reduces the speaker's anxiety, rests on 3 precise ingredients (empathy, attention, non-judgment), and makes you more likeable yourself.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"A friend shares a problem with you. What would you say right after they finish talking?","examples":["\"If I understand right, what's weighing on you most is... is that it?\"","\"That sounds really hard to go through, thanks for telling me.\"","\"Wait, so concretely, is it more X or Y that's bothering you?\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000013', 'rejet-social', $$Le rejet social, ça fait vraiment mal$$, $$Social rejection really does hurt$$, 13, ARRAY['rejet']::text[], false, 1, null, 'premium', $json${"hook":"On t'a ignoré dans une conversation de groupe, ou pire, exclu d'un truc auquel tout le monde a été invité sauf toi. La blessure te semble disproportionnée par rapport à \"juste\" un rejet social, comme si tu réagissais trop fort. Une étude en imagerie cérébrale a montré que ta réaction n'a rien d'exagéré : ton cerveau traite littéralement ça comme une douleur physique.","diagnostic":{"kind":"slider","question":"À quel point la peur d'être ignoré ou rejeté t'empêche-t-elle d'aller vers les autres ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Ça me bloque complètement"},"cards":[{"title":"Ton cerveau ne fait pas la différence","advice":"Une étude en IRMf a montré que l'exclusion sociale active le cortex cingulaire antérieur, la même zone cérébrale impliquée dans la douleur physique, et que cette activation est corrélée à la détresse ressentie.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"Donc ta réaction n'est pas \"exagérée\"","advice":"Cette douleur est neurologiquement réelle : ressentir une réaction forte face au rejet est le fonctionnement normal d'un cerveau humain, pas un signe d'hypersensibilité. Ça enlève une couche de honte inutile ajoutée à la douleur initiale.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"La douleur sociale est un signal, pas une sentence","advice":"Les chercheurs décrivent cette douleur comme une alarme : elle signale une rupture de lien à réparer, pas une preuve que tu ne mérites pas d'appartenir quelque part.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"Reprends contact plutôt que d'éviter","advice":"Éviter systématiquement toute situation où un nouveau rejet pourrait survenir entretient la douleur sur le long terme ; un petit pas de reconnexion, même minime, est plus protecteur que l'évitement complet.","sourceId":"a0000000-0000-0000-0000-000000000030"},{"title":"Récap","advice":"Le rejet active un vrai circuit de douleur cérébrale ; ta réaction n'est pas exagérée ; c'est un signal à traiter, pas une sentence ; reconnecte-toi plutôt que d'éviter.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Repense à un moment récent où tu t'es senti ignoré ou exclu. Écris la phrase que tu t'es dite sur toi-même à ce moment-là.","followUp":"Réécris-la en tenant compte du fait que c'est une douleur réelle, pas une preuve que tu as fait quelque chose de mal."}}$json$::jsonb, $json${"hook":"You got ignored in a group conversation, or worse, excluded from something everyone else was invited to. The hurt feels disproportionate for \"just\" a social rejection, as if you were overreacting. A brain-imaging study showed your reaction isn't exaggerated at all: your brain literally processes it as physical pain.","diagnostic":{"kind":"slider","question":"How much does the fear of being ignored or rejected stop you from reaching out to others?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"It blocks me completely"},"cards":[{"title":"Your brain doesn't tell the difference","advice":"An fMRI study showed that social exclusion activates the anterior cingulate cortex, the same brain region involved in physical pain, and that this activation is correlated with the distress reported.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"So your reaction isn't \"exaggerated\"","advice":"This pain is neurologically real: having a strong reaction to rejection is how a normal human brain works, not a sign of oversensitivity. That removes an unnecessary layer of shame on top of the initial pain.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"Social pain is a signal, not a sentence","advice":"Researchers describe this pain as an alarm: it signals a broken bond that needs repair, not proof that you don't deserve to belong somewhere.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"Reconnect rather than avoid","advice":"Systematically avoiding any situation where a new rejection might occur keeps the pain going long-term; a small step toward reconnecting, even a minor one, is more protective than complete avoidance.","sourceId":"a0000000-0000-0000-0000-000000000030"},{"title":"Recap","advice":"Rejection activates a real brain pain circuit; your reaction isn't exaggerated; it's a signal to act on, not a sentence; reconnect rather than avoid.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Think back to a recent moment when you felt ignored or excluded. Write down the thing you told yourself about yourself in that moment.","followUp":"Rewrite it knowing that this is real pain, not proof that you did something wrong."}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000014', 'reseauter-sans-se-forcer', $$Réseauter sans se forcer$$, $$Networking without forcing it$$, 14, ARRAY['travail', 'reseau']::text[], false, 1, null, 'premium', $json${"hook":"Un événement professionnel dans deux jours. Rien que d'y penser, tu sens déjà la fatigue : sourire poliment, faire semblant que tout ça sert à quelque chose, échanger des cartes de visite avec des gens que tu ne reverras jamais. Sauf qu'une étude fondatrice en sociologie, restée l'une des plus citées de son domaine, montre exactement le contraire : ce sont ces liens légers qui comptent le plus.","diagnostic":{"kind":"slider","question":"À quel point le réseautage professionnel te semble-t-il artificiel ou inutile ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Complètement"},"cards":[{"title":"Ce sont les liens faibles qui ouvrent des portes","advice":"Une étude devenue une référence en sociologie a interrogé des centaines de personnes sur la façon dont elles avaient trouvé leur emploi : leurs connaissances éloignées et occasionnelles se sont révélées statistiquement plus utiles que leurs proches pour accéder à de nouvelles opportunités.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Pourquoi ça marche : l'info ne se répète pas","advice":"Tes proches connaissent déjà ce que tu sais. Tes connaissances éloignées, elles, évoluent dans des cercles différents, et t'apportent des informations que ton entourage proche ne peut pas te donner.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Vise 1 lien, pas 20","advice":"Puisque la valeur vient des liens légers eux-mêmes, pas de leur nombre ni de leur intensité, l'objectif réaliste d'un événement n'est pas \"réseauter avec tout le monde\" mais repartir avec une seule connexion légère mais réelle.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Le suivi compte plus que la soirée","advice":"Un lien faible se maintient avec un minimum de contact périodique (un message tous les quelques mois suffit). Pas besoin d'intensité ni de fréquence pour qu'il reste utile.","sourceId":"a0000000-0000-0000-0000-000000000032"},{"title":"Récap","advice":"Les liens faibles sont statistiquement plus utiles que les liens forts pour les opportunités ; vise une seule connexion réelle par événement plutôt que la quantité ; entretiens-la avec un contact minimal mais régulier.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"Choisis une personne rencontrée récemment lors d'un événement pro. Quel message court pourrais-tu lui envoyer cette semaine pour garder le contact ?","examples":["\"Ravi d'avoir échangé l'autre jour, je repense à ce que tu disais sur [sujet], ça m'a donné à réfléchir !\"","\"Petit message pour garder le contact après notre échange à [événement], n'hésite pas si je peux t'être utile un jour.\""]}}$json$::jsonb, $json${"hook":"A professional event in two days. Just thinking about it, you already feel the fatigue: smiling politely, pretending any of this leads somewhere, trading business cards with people you'll never see again. Except a landmark sociology study, still one of the most cited in its field, shows exactly the opposite: it's these light connections that matter most.","diagnostic":{"kind":"slider","question":"How artificial or pointless does professional networking feel to you?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"Completely"},"cards":[{"title":"Weak ties are what open doors","advice":"A study that became a sociology landmark asked hundreds of people how they found their job: their distant, occasional acquaintances turned out to be statistically more useful than their close ones for accessing new opportunities.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Why it works: information doesn't repeat","advice":"Your close circle already knows what you know. Your distant acquaintances, on the other hand, move in different circles, and bring you information your close circle can't.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Aim for 1 connection, not 20","advice":"Since the value comes from the weak ties themselves, not their number or intensity, a realistic goal for an event isn't \"network with everyone\" but leaving with a single connection that's light but real.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Follow-up matters more than the event itself","advice":"A weak tie stays alive with minimal periodic contact (a message every few months is enough). No need for intensity or frequency for it to stay useful.","sourceId":"a0000000-0000-0000-0000-000000000032"},{"title":"Recap","advice":"Weak ties are statistically more useful than strong ties for opportunities; aim for one real connection per event rather than quantity; maintain it with minimal but regular contact.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"Pick someone you met recently at a professional event. What short message could you send them this week to stay in touch?","examples":["\"Great chatting the other day, I keep thinking about what you said about [topic], it really got me thinking!\"","\"Just a quick note to stay in touch after our chat at [event], let me know if I can ever help.\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000015', 'compliment-sincere', $$Faire un compliment sincère sans que ce soit bizarre$$, $$Giving a sincere compliment without it being weird$$, 15, ARRAY['compliment']::text[], false, 1, null, 'premium', $json${"hook":"Tu penses un vrai compliment à quelqu'un : sa façon de présenter les choses, un choix qu'il a fait, un détail que tu apprécies chez lui. Et tu le gardes pour toi, en imaginant que ça sonnerait faux ou gênant. Neuf expériences menées sur ce réflexe montrent que tu te trompes, et toujours dans le même sens.","diagnostic":{"kind":"slider","question":"À quel point retiens-tu des compliments sincères par peur que ce soit gênant ?","min":1,"max":10,"minLabel":"Jamais","maxLabel":"Presque toujours"},"cards":[{"title":"Tu sous-estimes l'effet, dans les deux sens","advice":"Sur neuf expériences, les personnes qui faisaient un compliment sous-estimaient systématiquement à quel point il rendrait l'autre heureux, tout en surestimant à quel point ce serait gênant. Les deux erreurs vont dans le même sens : celui qui te retient d'agir.","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"Ça ne s'use pas","advice":"Contrairement à l'intuition, répéter des compliments sincères à la même personne ne les rend pas moins sincères ni moins appréciés à ses yeux, l'effet ne s'épuise pas avec la répétition.","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"Sois précis, pas générique","advice":"Un compliment spécifique (\"ta façon d'expliquer ce point était hyper claire\") est perçu comme plus sincère et a plus d'impact qu'un compliment vague (\"t'es sympa\").","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"Dis-le sur le moment","advice":"Plus tu attends, plus l'occasion se referme et plus ton hésitation grandit : le compliment dit dans l'instant demande moins de courage que celui préparé après coup.","sourceId":"a0000000-0000-0000-0000-000000000034"},{"title":"Récap","advice":"Tu sous-estimes l'impact positif d'un compliment et surestimes sa gêne ; il ne s'use pas avec la répétition ; sois précis plutôt que vague ; dis-le sur le moment.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Pense à quelqu'un que tu vois régulièrement. Écris un compliment précis et sincère que tu pourrais lui faire cette semaine.","examples":["\"Ta façon d'expliquer ce dossier était hyper claire, j'ai tout de suite compris.\"","\"J'ai trouvé ta remarque en réunion hier super pertinente, ça a changé ma façon de voir le problème.\""]}}$json$::jsonb, $json${"hook":"You're thinking a genuine compliment about someone: the way they present things, a choice they made, a detail you appreciate about them. And you keep it to yourself, imagining it would sound fake or awkward. Nine experiments on this exact instinct show you're wrong, and always in the same direction.","diagnostic":{"kind":"slider","question":"How often do you hold back a sincere compliment for fear it would be awkward?","min":1,"max":10,"minLabel":"Never","maxLabel":"Almost always"},"cards":[{"title":"You underestimate the effect, in both directions","advice":"Across nine experiments, people giving a compliment consistently underestimated how happy it would make the other person, while overestimating how awkward it would be. Both errors point the same way: the way that stops you from acting.","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"It doesn't wear out","advice":"Contrary to intuition, repeating sincere compliments to the same person doesn't make them any less sincere or less appreciated, the effect doesn't fade with repetition.","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"Be specific, not generic","advice":"A specific compliment (\"the way you explained that point was really clear\") is perceived as more sincere and has more impact than a vague one (\"you're nice\").","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"Say it in the moment","advice":"The longer you wait, the more the window closes and the more your hesitation grows: a compliment given in the moment takes less courage than one prepared afterward.","sourceId":"a0000000-0000-0000-0000-000000000034"},{"title":"Recap","advice":"You underestimate a compliment's positive impact and overestimate its awkwardness; it doesn't wear out with repetition; be specific rather than vague; say it in the moment.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Think of someone you see regularly. Write a specific, sincere compliment you could give them this week.","examples":["\"The way you explained that report was really clear, I got it right away.\"","\"I thought your comment in the meeting yesterday was really sharp, it changed how I see the problem.\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000016', 'faire-monter-conversation', $$Faire monter une conversation$$, $$Taking a conversation deeper$$, 16, ARRAY['conversation']::text[], false, 2, 'b0000000-0000-0000-0000-000000000001', 'premium', $json${"hook":"La conversation dure depuis dix minutes. Météo, boulot, week-end. Tu sens qu'elle pourrait aller plus loin, mais une question un peu plus personnelle te semble risquée, comme si tu allais mettre l'autre mal à l'aise. Une étude sur plus de 1800 personnes a testé cette peur, en confrontant des inconnus à des questions bien plus profondes que la météo.","diagnostic":{"kind":"slider","question":"À quel point as-tu peur qu'une question plus personnelle mette l'autre mal à l'aise ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Énormément"},"cards":[{"title":"Ton estimation est fausse, dans le bon sens","advice":"Dans 12 expériences menées sur plus de 1800 participants, les conversations profondes entre inconnus se sont systématiquement révélées moins gênantes, plus connectantes et plus agréables que ce que les deux parties avaient prédit avant de commencer.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Monte d'un cran, pas de dix","advice":"Pas besoin de sauter directement à une question intime, une question légèrement plus personnelle que la moyenne (\"Qu'est-ce qui te motive dans ce que tu fais ?\" plutôt que \"Tu bosses où ?\") suffit à faire basculer une conversation vers plus de connexion.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Partage à la même profondeur","advice":"Dans l'étude, les échanges les plus connectants étaient réciproques : après avoir posé une question plus personnelle, partage aussi quelque chose d'un niveau de profondeur comparable sur toi-même.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Récap","advice":"Tu surestimes largement la gêne que provoque une question plus personnelle ; monte d'un cran progressivement ; partage à la même profondeur que ce que tu demandes.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Pense à une personne que tu connais un peu (collègue, connaissance) avec qui tu aimerais approfondir la conversation. Quelle question, légèrement plus personnelle que d'habitude, pourrais-tu lui poser ?","examples":["\"Qu'est-ce qui te motive vraiment dans ce que tu fais ?\"","\"C'est quoi un truc dont tu es vraiment fier ces derniers temps ?\""]}}$json$::jsonb, $json${"hook":"The conversation has been going for ten minutes. Weather, work, weekend. You sense it could go further, but a slightly more personal question feels risky, like you'd make the other person uncomfortable. A study of more than 1,800 people tested this fear, by having strangers ask each other questions far deeper than the weather.","diagnostic":{"kind":"slider","question":"How afraid are you that a more personal question would make the other person uncomfortable?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"Enormously"},"cards":[{"title":"Your estimate is wrong, in the good way","advice":"Across 12 experiments with more than 1,800 participants, deep conversations between strangers consistently turned out to be less awkward, more connecting, and more enjoyable than both sides had predicted going in.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Go up one notch, not ten","advice":"No need to jump straight to an intimate question, one slightly more personal than average (\"What motivates you in what you do?\" rather than \"Where do you work?\") is enough to shift a conversation toward more connection.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Share at the same depth","advice":"In the study, the most connecting exchanges were reciprocal: after asking a more personal question, share something about yourself at a comparable level of depth.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Recap","advice":"You significantly overestimate the awkwardness caused by a more personal question; go up one notch at a time; share at the same depth you're asking for.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Think of someone you know a little (a coworker, an acquaintance) you'd like to get to know better. What slightly more personal question than usual could you ask them?","examples":["\"What actually motivates you in what you do?\"","\"What's something you're genuinely proud of lately?\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000017', 'arreter-ruminations', $$Après l'événement : arrêter les ruminations$$, $$After the event: stopping the rumination$$, 17, ARRAY['anxiete', 'recuperation']::text[], false, 2, 'b0000000-0000-0000-0000-000000000005', 'premium', $json${"hook":"L'événement est terminé depuis des heures, mais toi, tu es encore dedans : tu repasses en boucle cette phrase que tu as mal formulée, ce silence bizarre, ce regard que tu as peut-être mal interprété. Ce phénomène a un nom précis en recherche clinique, et il a été mesuré : plus tu rumines, plus ton souvenir de l'événement se déforme dans le sens négatif.","diagnostic":{"kind":"slider","question":"Après un événement social, à quel point repasses-tu mentalement ce qui s'est dit ou ce que tu aurais dû dire ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"En boucle pendant des heures"},"cards":[{"title":"Ça s'appelle le \"post-event processing\"","advice":"C'est un phénomène mesuré et corrélé à l'anxiété sociale : des souvenirs récurrents et intrusifs de l'événement, qui interfèrent avec la concentration et poussent à éviter des situations similaires.","sourceId":"a0000000-0000-0000-0000-000000000022"},{"title":"Le souvenir se déforme pendant que tu rumines","advice":"Ce n'est pas un rejeu neutre : plus tu repasses l'événement, plus ton souvenir se biaise vers les détails négatifs, même si l'événement s'est objectivement bien passé. La rumination fabrique le souvenir qu'elle prétend analyser.","sourceId":"a0000000-0000-0000-0000-000000000022"},{"title":"Fixe une fenêtre, pas un accès illimité","advice":"Autorise-toi 10 minutes, à un moment précis de la journée, pour repenser à l'événement, puis stoppe consciemment en dehors de cette fenêtre. Contenir la rumination dans un créneau limité réduit son emprise sur le reste de la journée.","sourceId":"a0000000-0000-0000-0000-000000000023"},{"title":"Sépare les faits de l'histoire que tu te racontes","advice":"\"J'ai dit un truc bizarre\" est une interprétation, pas un fait. Écris ce qui s'est objectivement passé, puis à côté ce que tu en déduis sur toi. Les deux colonnes sont rarement aussi liées que ta rumination le laisse penser.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Récap","advice":"Le post-event processing est un phénomène identifié et mesurable ; la rumination déforme le souvenir plus qu'elle ne l'analyse ; limite-la à une fenêtre de temps ; sépare les faits des interprétations.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Pense à un événement social récent qui te trotte encore en tête. Colonne 1 : ce qui s'est objectivement passé, factuellement.","followUp":"Colonne 2 : ce que tu en déduis sur toi."}}$json$::jsonb, $json${"hook":"The event ended hours ago, but you're still in it: replaying that phrase you worded badly, that odd silence, that look you might have misread. This phenomenon has a precise name in clinical research, and it's been measured: the more you ruminate, the more your memory of the event distorts in a negative direction.","diagnostic":{"kind":"slider","question":"After a social event, how much do you mentally replay what was said or what you should have said?","min":1,"max":10,"minLabel":"Not at all","maxLabel":"On a loop for hours"},"cards":[{"title":"It's called \"post-event processing\"","advice":"It's a measured phenomenon correlated with social anxiety: recurring, intrusive memories of the event that interfere with concentration and push you to avoid similar situations.","sourceId":"a0000000-0000-0000-0000-000000000022"},{"title":"The memory distorts while you ruminate","advice":"It's not a neutral replay: the more you go over the event, the more your memory skews toward the negative details, even if the event objectively went fine. Rumination manufactures the memory it claims to be analyzing.","sourceId":"a0000000-0000-0000-0000-000000000022"},{"title":"Set a window, not unlimited access","advice":"Give yourself 10 minutes, at a specific time of day, to think back on the event, then consciously stop outside that window. Containing the rumination to a limited slot reduces its grip on the rest of the day.","sourceId":"a0000000-0000-0000-0000-000000000023"},{"title":"Separate the facts from the story you're telling yourself","advice":"\"I said something weird\" is an interpretation, not a fact. Write down what objectively happened, then next to it what you conclude about yourself. The two columns are rarely as connected as your rumination suggests.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Recap","advice":"Post-event processing is an identified, measurable phenomenon; rumination distorts the memory more than it analyzes it; limit it to a time window; separate facts from interpretations.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Think of a recent social event that's still on your mind. Column 1: what objectively happened, factually.","followUp":"Column 2: what you conclude about yourself from that."}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000018', 'entretenir-amitie', $$Entretenir une amitié dans la durée$$, $$Maintaining a friendship over time$$, 18, ARRAY['amitie']::text[], false, 2, 'b0000000-0000-0000-0000-000000000008', 'premium', $json${"hook":"Tu as mis des dizaines d'heures à devenir vraiment proche de quelqu'un. Et puis la vie prend le dessus, les semaines passent sans nouvelles, et le lien s'effiloche sans qu'aucune dispute n'ait eu lieu. Une étude longitudinale sur 18 mois a suivi ce phénomène. Bonne nouvelle : il obéit à des règles précises, pas au hasard.","diagnostic":{"kind":"slider","question":"Combien de tes amis proches as-tu contactés ce mois-ci ?","min":0,"max":10,"minLabel":"Aucun","maxLabel":"Tous"},"cards":[{"title":"L'amitié se dégrade sans contact, contrairement à la famille","advice":"Une étude longitudinale sur 18 mois montre que les liens familiaux résistent au manque de contact, mais que les amitiés, elles, se dégradent mesurablement sans entretien actif régulier.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Le rythme dépend de la proximité du cercle","advice":"Plus une amitié est proche, plus elle demande de fréquence : contact quasi quotidien pour le cercle le plus intime, hebdomadaire pour les amis proches, mensuel pour les cercles plus larges.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Pas le même levier pour tout le monde","advice":"La même étude observe une différence : le déclin est surtout évité par la fréquence des échanges (se parler) pour certains liens, et par les activités partagées pour d'autres. Identifie ce qui fonctionne le mieux avec chaque ami plutôt que d'appliquer la même recette à tous.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Programme-le, ne le laisse pas au hasard","advice":"Puisque la dégradation est passive (elle arrive sans qu'il y ait de conflit), la seule protection efficace est active : planifier le contact à l'avance plutôt que de compter sur l'envie spontanée.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Récap","advice":"Une amitié demande un entretien actif, contrairement à la famille ; adapte la fréquence à la proximité du lien ; identifie si c'est la conversation ou l'activité partagée qui compte le plus pour chaque ami ; planifie plutôt que d'attendre l'envie.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"Liste 3 amis proches. Pour chacun, quand les as-tu contactés pour la dernière fois ?","examples":["Programme un appel hebdomadaire avec ton ami le plus proche, même court.","Envoie un message simple à quelqu'un que tu n'as pas contacté depuis plus d'un mois : \"Je pensais à toi, comment tu vas ?\""]}}$json$::jsonb, $json${"hook":"You spent dozens of hours truly getting close to someone. Then life takes over, weeks go by without news, and the bond frays without any argument ever happening. An 18-month longitudinal study tracked this phenomenon. Good news: it follows precise rules, not chance.","diagnostic":{"kind":"slider","question":"How many of your close friends have you reached out to this month?","min":0,"max":10,"minLabel":"None","maxLabel":"All of them"},"cards":[{"title":"Friendship decays without contact, unlike family","advice":"An 18-month longitudinal study shows that family ties hold up despite a lack of contact, but friendships measurably decay without regular active upkeep.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"The right pace depends on how close the circle is","advice":"The closer a friendship, the more frequency it needs: near-daily contact for your innermost circle, weekly for close friends, monthly for wider circles.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Not the same lever for everyone","advice":"The same study found a difference: decline is avoided mainly through frequency of contact (talking) for some relationships, and through shared activities for others. Identify what works best with each friend rather than applying the same recipe to everyone.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Schedule it, don't leave it to chance","advice":"Since the decay is passive (it happens without any conflict), the only effective protection is active: planning contact in advance rather than counting on spontaneous desire.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Recap","advice":"A friendship needs active upkeep, unlike family; match the frequency to how close the bond is; figure out whether conversation or shared activity matters more for each friend; plan ahead rather than waiting to feel like it.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"List 3 close friends. For each, when did you last reach out to them?","examples":["Schedule a weekly call with your closest friend, even a short one.","Send a simple message to someone you haven't contacted in over a month: \"Was thinking of you, how are you doing?\""]}}$json$::jsonb)
